       int32_t fy_prev = fy_b;
       for (int32_t cx = cx0 + 1; cx < cx1; cx++)
       {
 	fy_b = fy_prev + delta_fy;
-	cell_add (area, cover, width, cx - x_org, 0, fy_prev, HB_RASTER_ONE_PIXEL, fy_b, wind, x_min, x_max);
