+    if (unlikely (cx1 >= col_limit))
       return; /* Entirely right of the surface. */

     int32_t x_b = (int32_t) hb_clamp ((int64_t) cx0 * HB_RASTER_ONE_PIXEL,
 				      (int64_t) INT32_MIN, (int64_t) INT32_MAX);
