+    cell_add_visible (area, cover, cx0 - x_org, fx0, fy0, 0, fy_b, wind, x_min, x_max);

     int32_t cx = cx0 - 1;
     int32_t fy_prev = fy_b;
-    if (unlikely (cx > col_max))
+    if (unlikely (cx >= col_limit))
     {
       /* Mid columns right of the surface contribute nothing. */
-      int32_t cx_skip = (int32_t) col_max; /* ≥ cx1, so it fits */
+      int32_t cx_skip = (int32_t) (col_limit - 1); /* ≥ cx1, so it fits */
       fy_prev = fy_b - (int32_t) ((int64_t) (cx - cx_skip) * delta_fy);
       cx = cx_skip;
     }
@@ -1447,7 +1459,7 @@ edge_sweep_row (int32_t                *area,
     for (; cx > cx_stop; cx--)
     {
       fy_b = fy_prev - delta_fy;
-      cell_add (area, cover, width, cx - x_org, HB_RASTER_ONE_PIXEL, fy_prev, 0, fy_b, wind, x_min, x_max);
+      cell_add_visible (area, cover, cx - x_org, HB_RASTER_ONE_PIXEL, fy_prev, 0, fy_b, wind, x_min, x_max);
       fy_prev = fy_b;
     }

